SELECT id, a.account_icon icon, account_name name, ( COALESCE(( SELECT SUM(cast(money as decimal(18, 2))) FROM px_bookkeeping_record r LEFT JOIN px_bookkeeping_classification c ON r.type = c.id WHERE account = a.id AND c.type_difference = '0' AND r.del_flag = 0
AND r.create_by IN
#{uid}
), 0 ) - COALESCE(( SELECT SUM(cast(money as decimal(18, 2))) FROM px_bookkeeping_record r LEFT JOIN px_bookkeeping_classification c ON r.type = c.id WHERE account = a.id AND c.type_difference = '1' AND r.del_flag = 0
AND r.create_by IN
#{uid}
), 0 ) + COALESCE((SELECT SUM(cast(money as decimal(18, 2))) FROM px_bookkeeping_record WHERE other_account = a.id AND type = 0 AND del_flag = 0
AND create_by IN
#{uid}
), 0) - COALESCE((SELECT SUM(cast(money as decimal(18, 2))) FROM px_bookkeeping_record WHERE account = a.id AND type = 0 AND del_flag = 0
AND create_by IN
#{uid}
), 0) + COALESCE( (SELECT SUM(cast(money as decimal(18, 2))) FROM px_bookkeeping_record WHERE account = a.id AND type = 1 AND del_flag = 0
AND create_by IN
#{uid}
), 0)) value FROM px_bookkeeping_account a WHERE a.del_flag = 0

SELECT left( pay_time, 7) 'name', sum(cast(money as decimal(18, 2))) 'value' FROM px_bookkeeping_record r left join px_bookkeeping_classification c on r.type = c.id WHERE r.del_flag = 0 AND c.del_flag = 0 AND LEFT( pay_time , 4 ) = LEFT(#{date} , 4) AND c.type_difference = #{typeDifference}
AND r.create_by IN
#{uid}
GROUP BY LEFT( pay_time, 7 )
